from pptx import Presentation
from pptx.util import Emu

p = Presentation('/root/Awesome-Agent-Papers.pptx')
print(f"Slide dims: W={p.slide_width} ({Emu(p.slide_width).inches}in) H={p.slide_height} ({Emu(p.slide_height).inches}in)")
for i, slide in enumerate(p.slides):
    print(f"\n=== Slide {i+1} (layout: {slide.slide_layout.name}) ===")
    for j, shape in enumerate(slide.shapes):
        ph_type = shape.placeholder_format.type if shape.is_placeholder else None
        info = f"  Shape[{j}]: name={shape.name!r}, type={shape.shape_type}, ph={ph_type}"
        try:
            info += f", pos=({Emu(shape.left).inches:.2f},{Emu(shape.top).inches:.2f}), size=({Emu(shape.width).inches:.2f}x{Emu(shape.height).inches:.2f})"
        except:
            pass
        print(info)
        if shape.has_text_frame:
            for k, para in enumerate(shape.text_frame.paragraphs):
                for r, run in enumerate(para.runs):
                    font = run.font
                    color_info = ""
                    try:
                        if font.color and font.color.rgb:
                            color_info = f" color={font.color.rgb}"
                    except:
                        pass
                    print(f"    P{k}R{r}: {run.text!r} font={font.name} size={font.size} bold={font.bold}{color_info}")
