{"command": "create", "path": "/tmp/verify.py", "file_text": "from pptx import Presentation
from pptx.util import Emu
from lxml import etree

p = Presentation('/root/Awesome-Agent-Papers_processed.pptx')
sw = Emu(p.slide_width).inches
sh = Emu(p.slide_height).inches
print(f"Slide: {sw}in x {sh}in  ({len(p.slides)} slides)")

for i, slide in enumerate(p.slides, 1):
    print(f"\n--- Slide {i} (layout: {slide.slide_layout.name}) ---")
    for j, shape in enumerate(slide.shapes):
        ph = shape.placeholder_format.type if shape.is_placeholder else None
        info = f"  Shape[{j}] name={shape.name!r} ph={ph}"
        try:
            info += f" pos=({Emu(shape.left).inches:.2f},{Emu(shape.top).inches:.2f}) size=({Emu(shape.width).inches:.2f}x{Emu(shape.height).inches:.2f})"
        except Exception:
            pass
        print(info)
        if shape.has_text_frame:
            for k, para in enumerate(shape.text_frame.paragraphs):
                for r, run in enumerate(para.runs):
                    f = run.font
                    c = ''
                    try:
                        if f.color and f.color.rgb:
                            c = f' color=#{f.color.rgb}'
                    except Exception:
                        pass
                    print(f"    P{k}R{r}: {run.text!r} font={f.name} size={f.size} bold={f.bold}{c}")
                # print pPr XML for reference slide bullets
                if para._pPr is not None:
                    print(f"    P{k} pPr: {etree.tostring(para._pPr, pretty_print=False).decode().strip()}")
"}

