            for k, para in enumerate(shape.text_frame.paragraphs):
                for r, run in enumerate(para.runs):
                    font = run.font
                    color_info = ""
                    try:
                        if font.color and font.color.rgb:
                            color_info = f" color={font.color.rgb}"
                    except Exception:
                        pass
                    print(f"    P{k}R{r}: {run.text!r} font={font.name} size={font.size} bold={font.bold}{color_info}")
